import{_ as n,C as l,o as t,c as r,a2 as a,b as o,w as s,a as d,E as p,a3 as h}from"./chunks/framework.CZqXuAiL.js";const w=JSON.parse('{"title":"Firewall-Plus","description":"Production-grade per-container iptables firewall for Pterodactyl Panel with a Wings node daemon, DDoS SMART detection, and automatic mitigation.","frontmatter":{"title":"Firewall-Plus","description":"Production-grade per-container iptables firewall for Pterodactyl Panel with a Wings node daemon, DDoS SMART detection, and automatic mitigation."},"headers":[],"relativePath":"firewall-plus/index.md","filePath":"firewall-plus/index.md","lastUpdated":1785501747000}'),c={name:"firewall-plus/index.md"};function u(g,e,k,m,b,f){const i=l("Mermaid");return t(),r("div",null,[e[1]||(e[1]=a('<h1 id="firewall-plus" tabindex="-1">Firewall-Plus <a class="header-anchor" href="#firewall-plus" aria-label="Permalink to &quot;Firewall-Plus&quot;">​</a></h1><p><strong>Production-grade per-container iptables firewall for Pterodactyl Panel</strong> — available as a Blueprint addon or a standalone panel extension — plus a Fastify node daemon on every Wings host, with DDoS SMART detection and automatic mitigation.</p><p>Firewall-Plus gives every game server its own iptables chains and ipsets, managed from the panel UI your users already know. Rules are applied atomically on the node through a queued, snapshot-backed pipeline, and the SMART engine watches live traffic on the node and mitigates attacks before they take a server down.</p><div class="tip custom-block" style="margin-top:1.5rem;"><p><strong>Built for PingLess Studios by <a href="https://github.com/AnAverageBeing" target="_blank" rel="noreferrer">AnAverageBeing</a></strong><a href="https://github.com/AnAverageBeing/pterodactyl-firewall-plus" target="_blank" rel="noreferrer">GitHub Repo</a> · <a href="https://studio.pingless.org" target="_blank" rel="noreferrer">Studio</a></p></div><hr><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2>',6)),(t(),o(h,null,{default:s(()=>[p(i,{id:"mermaid-18",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20subgraph%20Panel%5BPterodactyl%20Panel%5D%0A%20%20%20%20%20%20%20%20UI%5BClient%20Firewall%20UI%5D%20--%3E%20API%5BClient%20API%20%2Fv1%2Ffirewall%5D%0A%20%20%20%20%20%20%20%20ADMIN%5BAdmin%20Area%5D%20--%3E%20DB%5B(Firewall%20Tables)%5D%0A%20%20%20%20%20%20%20%20API%20--%3E%20JOB%5BApplyFirewallRulesJob%5D%0A%20%20%20%20%20%20%20%20DB%20--%3E%20JOB%0A%20%20%20%20%20%20%20%20SCHED%5BScheduler%20%2B%20Queue%20Worker%5D%20--%3E%20JOB%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Node%5BWings%20Node%5D%0A%20%20%20%20%20%20%20%20JOB%20--%3E%7CHTTPS%2FHTTP%20%2B%20Bearer%7C%20NS%5Bfirewall-plus%20daemon%20%3A8472%5D%0A%20%20%20%20%20%20%20%20NS%20--%3E%20QUEUE%5BQueueManager%5D%0A%20%20%20%20%20%20%20%20QUEUE%20--%3E%20APPLY%5BAtomic%20iptables-restore%5D%0A%20%20%20%20%20%20%20%20APPLY%20--%3E%20IPT%5Biptables%20%2B%20ipset%5D%0A%20%20%20%20%20%20%20%20NS%20--%3E%20SMART%5BSMART%20Monitor%20-%20EWMA%5D%0A%20%20%20%20%20%20%20%20SMART%20--%3E%20MIT%5BL1-L3%20Mitigations%5D%0A%20%20%20%20%20%20%20%20SMART%20--%3E%7Cevents%20sync%7C%20Panel%0A%20%20%20%20end%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a(`<p>The <strong>panel</strong> owns all state: rules, lists, presets, grants, audit logs, and SMART events. The <strong>node daemon</strong> is a small Fastify service (default port <code>8472</code>) that turns panel payloads into atomic iptables changes, verifies them for drift, and runs the SMART detection loop locally on the host.</p><hr><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><ul><li><strong>13 rule types</strong> — SYN/TCP/UDP/connection limits, global packet limit, fragment drop, TTL filter, packet-size filter, new-connection rate, stateful tracking, burst protection, and GeoIP filtering. See <a href="./user-guide/rules">Rule Types</a>.</li><li><strong>ipset whitelist &amp; blacklist</strong> — per-server <code>fwp-wl-*</code> / <code>fwp-bl-*</code> ipsets with bulk import, applied atomically with rule changes.</li><li><strong>Per-port or global scopes</strong> — rules can target a single allocation port (<code>FWP-{server}-{port}</code> chains) or the whole server (<code>FWP-{server}</code> chain), plus built-in game presets.</li><li><strong>SMART DDoS detection</strong> — on-node EWMA anomaly detection with L1→L3 mitigations, cooldowns, attack event log, per-server owner Discord webhooks <strong>and</strong> owner email alerts, and event acknowledgement from both the client UI and the admin Activity page.</li><li><strong>Atomic, safe applies</strong> — every apply is queued, written via <code>iptables-restore</code>, snapshotted first, and rolled back automatically on failure. Drift detection and reconcile keep nodes honest.</li><li><strong>Full admin operations area</strong> — nodes (tokens, health, version), servers (grants, SMART grants, sync states), rule CRUD, presets, activity audit, operations queue, emergency controls (freeze, per-rule-type disable, flush-all), and settings.</li><li><strong>Rich client area</strong> — dashboard with charts (chart.js), rules editor, whitelist/blacklist, presets, logs, SMART tab, AbuseIPDB tab, config import/export, and a Terms-of-Service gate.</li><li><strong>Hardened node daemon</strong> — bearer-token auth, IP whitelist, per-route rate limits, systemd sandboxing, and correlation IDs end-to-end.</li></ul><hr><h2 id="blueprint-vs-standalone" tabindex="-1">Blueprint vs Standalone <a class="header-anchor" href="#blueprint-vs-standalone" aria-label="Permalink to &quot;Blueprint vs Standalone&quot;">​</a></h2><p>The panel extension ships in two flavors. Both install the <strong>same</strong> panel code and features — the difference is how the files get into your panel.</p><table tabindex="0"><thead><tr><th></th><th>Blueprint (recommended)</th><th>Standalone</th></tr></thead><tbody><tr><td>Installer</td><td><code>blueprint -install pterodactylfirewallplus-vX.Y.Z.blueprint</code></td><td><code>sudo bash install.sh</code> from the <code>standalone/</code> folder</td></tr><tr><td>Requirement</td><td><a href="https://blueprint.zip" target="_blank" rel="noreferrer">Blueprint</a> framework installed on the panel</td><td>None — plain Pterodactyl panel</td></tr><tr><td>File merging</td><td>Automatic via Blueprint</td><td><code>install.sh</code> copies <code>PanelFiles</code> into place</td></tr><tr><td>Removal</td><td><code>blueprint -remove pterodactylfirewallplus</code></td><td><code>sudo bash uninstall.sh</code></td></tr><tr><td>Updates</td><td>Install the new <code>.blueprint</code> package</td><td>Re-run <code>install.sh</code> from the new release</td></tr><tr><td>Panel version coupling</td><td>Managed by Blueprint compatibility flags</td><td>Manual — check release notes</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">The node daemon is separate either way</p><p>Reinstalling or upgrading the panel extension does <strong>not</strong> update the node service. The node daemon is installed once per Wings host and upgraded independently. See <a href="./getting-started/installation#node-installation">Installation</a>.</p></div><hr><h2 id="quick-install" tabindex="-1">Quick Install <a class="header-anchor" href="#quick-install" aria-label="Permalink to &quot;Quick Install&quot;">​</a></h2><p><strong>Panel (Blueprint):</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pterodactylfirewallplus-v1.2.6.blueprint</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span></span></code></pre></div><p><strong>Each Wings node:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://fw-install.pingless.org/node/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8472/api/v1/health</span></span></code></pre></div><p>Then add the node in <strong>Admin → Firewall → Nodes</strong>, and make sure the scheduler cron and queue worker are running. Full walkthrough: <a href="./getting-started/installation">Installation</a> · <a href="./getting-started/quick-start">Quick Start</a></p>`,16))])}const F=n(c,[["render",u]]);export{w as __pageData,F as default};
